-- ======================================================================
-- 20260913000100_phase01_profiles_and_audit.sql
-- ======================================================================

-- =============================================================================
-- Phase 01 — Authentication, RBAC and Security
--
-- Creates: profiles, audit_logs, the profile-creation trigger, and RLS.
--
-- Write-path rule (master plan §33):
--   The browser role gets SELECT on its own rows and nothing else.
--   Every INSERT / UPDATE / DELETE goes through a server action using the
--   service role, which checks ownership in code before writing.
--
-- Rationale: with the anon key the browser reaches PostgREST directly, so RLS
-- cannot distinguish the service layer from devtools. A column the client
-- never sends is a column the client cannot set.
--
-- Idempotent: safe to re-run.
-- =============================================================================

-- -----------------------------------------------------------------------------
-- profiles
-- -----------------------------------------------------------------------------

create table if not exists public.profiles (
  id               uuid primary key references auth.users (id) on delete cascade,
  email            text,
  full_name        text,
  avatar_url       text,
  role             text        not null default 'user',
  status           text        not null default 'active',
  -- Asia/Manila is assumed by phases 02, 03, 06, 07, 08, 09 and 12 for
  -- transaction dates, due-date comparison, analytics month boundaries,
  -- forecast dates, usage periods and relative date parsing. One
  -- authoritative value beats seven hardcoded strings.
  timezone         text        not null default 'Asia/Manila',
  default_currency text        not null default 'PHP',
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now()
);

comment on table public.profiles is
  'Application-level user record. 1:1 with auth.users. role and status have no client-writable path.';

-- Constraints added defensively: Postgres has no ADD CONSTRAINT IF NOT EXISTS.
do $$
begin
  if not exists (
    select 1 from pg_constraint
    where conname = 'profiles_role_check' and conrelid = 'public.profiles'::regclass
  ) then
    alter table public.profiles
      add constraint profiles_role_check check (role in ('user', 'admin'));
  end if;

  if not exists (
    select 1 from pg_constraint
    where conname = 'profiles_status_check' and conrelid = 'public.profiles'::regclass
  ) then
    alter table public.profiles
      add constraint profiles_status_check
      check (status in ('active', 'suspended', 'disabled'));
  end if;

  if not exists (
    select 1 from pg_constraint
    where conname = 'profiles_currency_check' and conrelid = 'public.profiles'::regclass
  ) then
    alter table public.profiles
      add constraint profiles_currency_check check (char_length(default_currency) = 3);
  end if;
end $$;

-- RLS policies filter on id; the primary key index already covers it.
-- Partial index for the admin lookup, which is rare and highly selective.
create index if not exists profiles_role_idx
  on public.profiles (role) where role = 'admin';

create index if not exists profiles_status_idx
  on public.profiles (status) where status <> 'active';

-- -----------------------------------------------------------------------------
-- audit_logs
--
-- Created with the FULL shape Phase 02 needs, not a reduced one. Phase 01 only
-- populates the auth-event columns and leaves entity/diff columns null — but
-- creating the narrow shape now would mean an ALTER on Phase 02's first day.
-- -----------------------------------------------------------------------------

create table if not exists public.audit_logs (
  id             uuid        primary key default gen_random_uuid(),
  actor_user_id  uuid        references auth.users (id) on delete set null,
  target_user_id uuid        references auth.users (id) on delete set null,
  entity_type    text,
  entity_id      uuid,
  event_type     text        not null,
  before_data    jsonb,
  after_data     jsonb,
  metadata       jsonb       not null default '{}'::jsonb,
  created_at     timestamptz not null default now()
);

comment on table public.audit_logs is
  'Append-only. No UPDATE or DELETE policy exists for any role, including the user who owns the row.';

create index if not exists audit_logs_target_created_idx
  on public.audit_logs (target_user_id, created_at desc);

create index if not exists audit_logs_entity_idx
  on public.audit_logs (entity_type, entity_id);

-- -----------------------------------------------------------------------------
-- updated_at maintenance
-- -----------------------------------------------------------------------------

create or replace function public.set_updated_at()
returns trigger
language plpgsql
security invoker
set search_path = ''
as $$
begin
  new.updated_at := now();
  return new;
end;
$$;

drop trigger if exists profiles_set_updated_at on public.profiles;
create trigger profiles_set_updated_at
  before update on public.profiles
  for each row execute function public.set_updated_at();

-- -----------------------------------------------------------------------------
-- Profile creation on signup
--
-- A database trigger rather than application code, so email/password and
-- Google OAuth produce identical results. Application-side creation would have
-- to be duplicated per provider and would silently skip if a signup path were
-- added later.
--
-- SECURITY DEFINER because it writes to a table the signing-up user has no
-- INSERT privilege on. search_path is pinned to empty to prevent search-path
-- hijacking — mandatory for any SECURITY DEFINER function.
-- -----------------------------------------------------------------------------

create or replace function public.handle_new_user()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  insert into public.profiles (id, email, full_name, avatar_url, role, status)
  values (
    new.id,
    new.email,
    -- Google returns full_name or name; email signup may send full_name.
    coalesce(
      new.raw_user_meta_data ->> 'full_name',
      new.raw_user_meta_data ->> 'name'
    ),
    coalesce(
      new.raw_user_meta_data ->> 'avatar_url',
      new.raw_user_meta_data ->> 'picture'
    ),
    -- Never read role from user metadata. OAuth metadata is attacker-adjacent
    -- and sign-up payloads are client-controlled.
    'user',
    'active'
  )
  on conflict (id) do nothing;

  return new;
end;
$$;

drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created
  after insert on auth.users
  for each row execute function public.handle_new_user();

-- Backfill any users that predate this migration.
insert into public.profiles (id, email, full_name, avatar_url, role, status)
select
  u.id,
  u.email,
  coalesce(u.raw_user_meta_data ->> 'full_name', u.raw_user_meta_data ->> 'name'),
  coalesce(u.raw_user_meta_data ->> 'avatar_url', u.raw_user_meta_data ->> 'picture'),
  'user',
  'active'
from auth.users u
on conflict (id) do nothing;

-- -----------------------------------------------------------------------------
-- Row Level Security
-- -----------------------------------------------------------------------------

alter table public.profiles   enable row level security;
alter table public.profiles   force  row level security;
alter table public.audit_logs enable row level security;
alter table public.audit_logs force  row level security;

-- profiles: read own row only.
-- auth.uid() is wrapped in a subselect so it is evaluated once per query
-- rather than once per row.
drop policy if exists profiles_select_own on public.profiles;
create policy profiles_select_own
  on public.profiles
  for select
  to authenticated
  using (id = (select auth.uid()));

-- No INSERT / UPDATE / DELETE policy for `authenticated`, deliberately.
-- Inserts come from the trigger (SECURITY DEFINER); updates come from server
-- actions using the service role, which bypasses RLS and is never exposed to
-- the browser.

-- audit_logs: read own history. Append-only for everyone.
drop policy if exists audit_logs_select_own on public.audit_logs;
create policy audit_logs_select_own
  on public.audit_logs
  for select
  to authenticated
  using (target_user_id = (select auth.uid()));

-- -----------------------------------------------------------------------------
-- Least privilege
-- -----------------------------------------------------------------------------

revoke all on public.profiles   from anon, authenticated;
revoke all on public.audit_logs from anon, authenticated;

grant select on public.profiles   to authenticated;
grant select on public.audit_logs to authenticated;

-- anon gets nothing: an unauthenticated visitor has no rows to see.


-- ======================================================================
-- 20260913000200_phase02_financial_core.sql
-- ======================================================================

-- =============================================================================
-- Phase 02 — Financial Core
--
-- accounts, categories, transactions, tags, transaction_tags.
--
-- Two rules this schema enforces rather than trusts:
--
--   1. amount is ALWAYS positive. Direction comes from transaction type and
--      account role (see lib/finance/balance.ts), never from a stored sign.
--   2. accounts.opening_balance is input-only. The authoritative opening
--      amount is an opening_balance TRANSACTION. Summing both would make every
--      account wrong by exactly its opening amount, in a way that reconciles
--      against nothing.
--
-- Write-path rule (master plan §33): browser gets SELECT on own rows; all
-- mutations go through server actions using the service role.
--
-- Idempotent.
-- =============================================================================

-- -----------------------------------------------------------------------------
-- accounts
-- -----------------------------------------------------------------------------

create table if not exists public.accounts (
  id               uuid primary key default gen_random_uuid(),
  user_id          uuid not null references auth.users (id) on delete cascade,
  name             text not null,
  type             text not null,
  nature           text not null,
  currency_code    text not null default 'PHP',
  -- Input-only. Never summed. See header.
  opening_balance  numeric(18, 2) not null default 0,
  -- Cache. Always recomputable from transactions via recalculate_account_balance().
  current_balance  numeric(18, 2) not null default 0,
  institution_name text,
  is_active        boolean not null default true,
  is_archived      boolean not null default false,
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now()
);

comment on column public.accounts.opening_balance is
  'What the user typed when creating the account. Display and audit only — NEVER summed into a balance. The opening_balance transaction is authoritative.';
comment on column public.accounts.current_balance is
  'Cached. Derived from transactions; recomputable at any time. Never client-writable.';

do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'accounts_type_check') then
    alter table public.accounts add constraint accounts_type_check
      check (type in ('cash','bank','gcash','maya','paypal','credit_card','loan','investment','other'));
  end if;
  if not exists (select 1 from pg_constraint where conname = 'accounts_nature_check') then
    alter table public.accounts add constraint accounts_nature_check
      check (nature in ('asset','liability'));
  end if;
  if not exists (select 1 from pg_constraint where conname = 'accounts_currency_check') then
    alter table public.accounts add constraint accounts_currency_check
      check (char_length(currency_code) = 3);
  end if;
  if not exists (select 1 from pg_constraint where conname = 'accounts_name_check') then
    alter table public.accounts add constraint accounts_name_check
      check (char_length(btrim(name)) between 1 and 80);
  end if;
end $$;

create index if not exists accounts_user_idx on public.accounts (user_id);
create index if not exists accounts_user_active_idx
  on public.accounts (user_id) where is_archived = false;

drop trigger if exists accounts_set_updated_at on public.accounts;
create trigger accounts_set_updated_at before update on public.accounts
  for each row execute function public.set_updated_at();

-- -----------------------------------------------------------------------------
-- categories
--
-- System categories have user_id null and are readable by everyone.
-- -----------------------------------------------------------------------------

create table if not exists public.categories (
  id          uuid primary key default gen_random_uuid(),
  user_id     uuid references auth.users (id) on delete cascade,
  name        text not null,
  type        text not null,
  icon        text,
  is_system   boolean not null default false,
  is_active   boolean not null default true,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now()
);

do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'categories_type_check') then
    alter table public.categories add constraint categories_type_check
      check (type in ('income','expense','both'));
  end if;
  -- A system category must have no owner; a user category must have one.
  if not exists (select 1 from pg_constraint where conname = 'categories_ownership_check') then
    alter table public.categories add constraint categories_ownership_check
      check ((is_system and user_id is null) or (not is_system and user_id is not null));
  end if;
end $$;

create index if not exists categories_user_idx on public.categories (user_id);
create unique index if not exists categories_system_name_idx
  on public.categories (lower(name), type) where is_system;

drop trigger if exists categories_set_updated_at on public.categories;
create trigger categories_set_updated_at before update on public.categories
  for each row execute function public.set_updated_at();

-- -----------------------------------------------------------------------------
-- transactions
-- -----------------------------------------------------------------------------

create table if not exists public.transactions (
  id                       uuid primary key default gen_random_uuid(),
  user_id                  uuid not null references auth.users (id) on delete cascade,
  type                     text not null,
  direction                text,
  amount                   numeric(18, 2) not null,
  currency_code            text not null default 'PHP',
  transaction_date         date not null,
  source_account_id        uuid references public.accounts (id) on delete restrict,
  destination_account_id   uuid references public.accounts (id) on delete restrict,
  category_id              uuid references public.categories (id) on delete set null,
  merchant_name            text,
  description              text,
  notes                    text,
  refund_of_transaction_id uuid references public.transactions (id) on delete set null,
  transfer_group_id        uuid,
  status                   text not null default 'confirmed',
  void_reason              text,
  is_archived              boolean not null default false,
  created_at               timestamptz not null default now(),
  updated_at               timestamptz not null default now()
);

comment on column public.transactions.amount is
  'ALWAYS positive. Direction is derived from type and account role — see lib/finance/balance.ts §34.';

do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'transactions_amount_check') then
    alter table public.transactions add constraint transactions_amount_check
      check (amount > 0);
  end if;
  if not exists (select 1 from pg_constraint where conname = 'transactions_type_check') then
    alter table public.transactions add constraint transactions_type_check
      check (type in ('income','expense','transfer','refund','adjustment','opening_balance'));
  end if;
  if not exists (select 1 from pg_constraint where conname = 'transactions_status_check') then
    alter table public.transactions add constraint transactions_status_check
      check (status in ('confirmed','voided'));
  end if;
  if not exists (select 1 from pg_constraint where conname = 'transactions_direction_check') then
    alter table public.transactions add constraint transactions_direction_check
      check (direction is null or direction in ('increase','decrease'));
  end if;
  if not exists (select 1 from pg_constraint where conname = 'transactions_currency_check') then
    alter table public.transactions add constraint transactions_currency_check
      check (char_length(currency_code) = 3);
  end if;
  if not exists (select 1 from pg_constraint where conname = 'transactions_distinct_accounts_check') then
    alter table public.transactions add constraint transactions_distinct_accounts_check
      check (source_account_id is null
             or destination_account_id is null
             or source_account_id <> destination_account_id);
  end if;

  -- §34a encoded in the database, so a service bug cannot write an
  -- unbalanceable row. These are the shapes lib/finance/balance.ts assumes.
  if not exists (select 1 from pg_constraint where conname = 'transactions_shape_check') then
    alter table public.transactions add constraint transactions_shape_check check (
      case type
        when 'income'          then destination_account_id is not null and source_account_id is null
        when 'refund'          then destination_account_id is not null and source_account_id is null
        when 'opening_balance' then destination_account_id is not null and source_account_id is null
        when 'expense'         then source_account_id is not null and destination_account_id is null
        when 'adjustment'      then source_account_id is not null and destination_account_id is null
                                    and direction is not null
        when 'transfer'        then source_account_id is not null and destination_account_id is not null
        else false
      end
    );
  end if;
end $$;

create index if not exists transactions_user_date_idx
  on public.transactions (user_id, transaction_date desc);
create index if not exists transactions_user_type_idx
  on public.transactions (user_id, type);
create index if not exists transactions_user_category_idx
  on public.transactions (user_id, category_id);
create index if not exists transactions_source_idx
  on public.transactions (source_account_id) where source_account_id is not null;
create index if not exists transactions_destination_idx
  on public.transactions (destination_account_id) where destination_account_id is not null;
-- Partial: analytics and balances read confirmed rows almost exclusively.
create index if not exists transactions_confirmed_idx
  on public.transactions (user_id, transaction_date desc) where status = 'confirmed';

drop trigger if exists transactions_set_updated_at on public.transactions;
create trigger transactions_set_updated_at before update on public.transactions
  for each row execute function public.set_updated_at();

-- -----------------------------------------------------------------------------
-- tags
-- -----------------------------------------------------------------------------

create table if not exists public.tags (
  id         uuid primary key default gen_random_uuid(),
  user_id    uuid not null references auth.users (id) on delete cascade,
  name       text not null,
  created_at timestamptz not null default now()
);

create unique index if not exists tags_user_name_idx on public.tags (user_id, lower(name));

create table if not exists public.transaction_tags (
  transaction_id uuid not null references public.transactions (id) on delete cascade,
  tag_id         uuid not null references public.tags (id) on delete cascade,
  user_id        uuid not null references auth.users (id) on delete cascade,
  primary key (transaction_id, tag_id)
);

create index if not exists transaction_tags_tag_idx on public.transaction_tags (tag_id);

-- -----------------------------------------------------------------------------
-- Balance derivation
--
-- The SQL mirror of lib/finance/balance.ts §34. Both must agree; the tests in
-- lib/finance/balance.test.ts define the contract.
-- -----------------------------------------------------------------------------

create or replace function public.recalculate_account_balance(p_account_id uuid)
returns numeric
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_nature  text;
  v_balance numeric(18, 2);
begin
  select nature into v_nature from public.accounts where id = p_account_id;
  if v_nature is null then
    raise exception 'No account %', p_account_id;
  end if;

  select coalesce(sum(
    case
      -- as SOURCE
      when t.source_account_id = p_account_id then
        case t.type
          when 'expense'    then case when v_nature = 'asset' then -t.amount else  t.amount end
          when 'transfer'   then case when v_nature = 'asset' then -t.amount else  t.amount end
          when 'adjustment' then case when t.direction = 'decrease' then -t.amount else t.amount end
          else 0
        end
      -- as DESTINATION
      when t.destination_account_id = p_account_id then
        case t.type
          when 'income'          then case when v_nature = 'asset' then t.amount else 0 end
          when 'refund'          then case when v_nature = 'asset' then t.amount else -t.amount end
          when 'transfer'        then case when v_nature = 'asset' then t.amount else -t.amount end
          when 'opening_balance' then case when t.direction = 'decrease' then -t.amount else t.amount end
          else 0
        end
      else 0
    end
  ), 0)
  into v_balance
  from public.transactions t
  where t.status = 'confirmed'
    and (t.source_account_id = p_account_id or t.destination_account_id = p_account_id);

  update public.accounts set current_balance = v_balance where id = p_account_id;
  return v_balance;
end;
$$;

comment on function public.recalculate_account_balance(uuid) is
  'Derives the authoritative balance from confirmed transactions only. accounts.opening_balance is deliberately excluded.';

-- -----------------------------------------------------------------------------
-- Seed system categories (§13, §14)
-- -----------------------------------------------------------------------------

insert into public.categories (user_id, name, type, is_system)
select null, name, 'expense', true
from (values
  ('Food'),('Transportation'),('Housing'),('Utilities'),('Loans'),('Education'),
  ('Health'),('Shopping'),('Entertainment'),('Subscriptions'),('Fitness'),
  ('Car'),('Business'),('Technology'),('Travel'),('Other')
) as t(name)
on conflict do nothing;

insert into public.categories (user_id, name, type, is_system)
select null, name, 'income', true
from (values
  ('Salary'),('Freelance'),('Business Income'),('Allowance'),
  ('Refund'),('Interest'),('Investment Income'),('Other Income')
) as t(name)
on conflict do nothing;

-- -----------------------------------------------------------------------------
-- Row Level Security
-- -----------------------------------------------------------------------------

alter table public.accounts         enable row level security;
alter table public.accounts         force  row level security;
alter table public.categories       enable row level security;
alter table public.categories       force  row level security;
alter table public.transactions     enable row level security;
alter table public.transactions     force  row level security;
alter table public.tags             enable row level security;
alter table public.tags             force  row level security;
alter table public.transaction_tags enable row level security;
alter table public.transaction_tags force  row level security;

drop policy if exists accounts_select_own on public.accounts;
create policy accounts_select_own on public.accounts
  for select to authenticated using (user_id = (select auth.uid()));

-- System categories are shared; user categories are private.
drop policy if exists categories_select on public.categories;
create policy categories_select on public.categories
  for select to authenticated
  using (is_system or user_id = (select auth.uid()));

drop policy if exists transactions_select_own on public.transactions;
create policy transactions_select_own on public.transactions
  for select to authenticated using (user_id = (select auth.uid()));

drop policy if exists tags_select_own on public.tags;
create policy tags_select_own on public.tags
  for select to authenticated using (user_id = (select auth.uid()));

drop policy if exists transaction_tags_select_own on public.transaction_tags;
create policy transaction_tags_select_own on public.transaction_tags
  for select to authenticated using (user_id = (select auth.uid()));

-- No INSERT / UPDATE / DELETE policies for `authenticated`, deliberately.

revoke all on public.accounts, public.categories, public.transactions,
              public.tags, public.transaction_tags
  from anon, authenticated;

grant select on public.accounts, public.categories, public.transactions,
                public.tags, public.transaction_tags
  to authenticated;


-- ======================================================================
-- 20260913000300_phase02_transaction_rpc.sql
-- ======================================================================

-- =============================================================================
-- Phase 02 — atomic transaction operations (§37, §64)
--
-- Creating, editing and voiding a transaction each touch a row plus one or two
-- cached balances. Done as separate statements from application code, a crash
-- or a concurrent request between them leaves a balance that disagrees with the
-- ledger — and nothing surfaces it until someone reconciles by hand.
--
-- So each operation is one SQL function: one transaction, all or nothing.
--
-- Ownership is verified INSIDE each function against p_user_id, which callers
-- resolve from the session. These are SECURITY DEFINER, so they bypass RLS —
-- the ownership check here is the only thing standing between a caller and
-- another user's accounts.
-- =============================================================================

-- Shared: assert every referenced account belongs to the user and matches the
-- transaction currency. Raises rather than returning, so a caller cannot
-- accidentally ignore the result.
create or replace function public.assert_account_access(
  p_user_id       uuid,
  p_account_id    uuid,
  p_currency_code text
)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_owner    uuid;
  v_currency text;
  v_archived boolean;
begin
  if p_account_id is null then
    return;
  end if;

  select user_id, currency_code, is_archived
    into v_owner, v_currency, v_archived
  from public.accounts
  where id = p_account_id;

  if v_owner is null then
    raise exception 'ACCOUNT_NOT_FOUND' using errcode = 'P0002';
  end if;
  if v_owner <> p_user_id then
    -- Same error as not-found on purpose: a distinguishable "forbidden"
    -- confirms the account exists, which is an enumeration oracle.
    raise exception 'ACCOUNT_NOT_FOUND' using errcode = 'P0002';
  end if;
  if v_archived then
    raise exception 'ACCOUNT_ARCHIVED' using errcode = 'P0001';
  end if;
  if v_currency <> p_currency_code then
    -- HelloPera never converts (master plan §11).
    raise exception 'CURRENCY_MISMATCH' using errcode = 'P0001';
  end if;
end;
$$;

-- -----------------------------------------------------------------------------
-- create_transaction
-- -----------------------------------------------------------------------------

create or replace function public.create_transaction(
  p_user_id              uuid,
  p_type                 text,
  p_amount               numeric,
  p_currency_code        text,
  p_transaction_date     date,
  p_source_account_id    uuid   default null,
  p_destination_account_id uuid default null,
  p_category_id          uuid   default null,
  p_direction            text   default null,
  p_merchant_name        text   default null,
  p_description          text   default null,
  p_notes                text   default null,
  p_refund_of            uuid   default null
)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_id uuid;
begin
  if p_amount is null or p_amount <= 0 then
    raise exception 'AMOUNT_NOT_POSITIVE' using errcode = 'P0001';
  end if;

  perform public.assert_account_access(p_user_id, p_source_account_id, p_currency_code);
  perform public.assert_account_access(p_user_id, p_destination_account_id, p_currency_code);

  if p_category_id is not null then
    if not exists (
      select 1 from public.categories
      where id = p_category_id and (is_system or user_id = p_user_id)
    ) then
      raise exception 'CATEGORY_NOT_FOUND' using errcode = 'P0002';
    end if;
  end if;

  -- Lock the affected accounts in a stable order (by id) so two concurrent
  -- writes touching the same pair cannot deadlock by grabbing them opposite
  -- ways round.
  perform 1 from public.accounts
  where id in (p_source_account_id, p_destination_account_id)
  order by id
  for update;

  insert into public.transactions (
    user_id, type, direction, amount, currency_code, transaction_date,
    source_account_id, destination_account_id, category_id,
    merchant_name, description, notes, refund_of_transaction_id, status
  ) values (
    p_user_id, p_type, p_direction, p_amount, p_currency_code, p_transaction_date,
    p_source_account_id, p_destination_account_id, p_category_id,
    nullif(btrim(coalesce(p_merchant_name, '')), ''),
    nullif(btrim(coalesce(p_description, '')), ''),
    nullif(btrim(coalesce(p_notes, '')), ''),
    p_refund_of, 'confirmed'
  )
  returning id into v_id;

  -- Recompute from the ledger rather than incrementing the cache: an
  -- increment that runs twice is undetectable, a recompute is idempotent.
  if p_source_account_id is not null then
    perform public.recalculate_account_balance(p_source_account_id);
  end if;
  if p_destination_account_id is not null then
    perform public.recalculate_account_balance(p_destination_account_id);
  end if;

  insert into public.audit_logs
    (actor_user_id, target_user_id, entity_type, entity_id, event_type, after_data)
  values
    (p_user_id, p_user_id, 'transaction', v_id, 'transaction_created',
     jsonb_build_object('type', p_type, 'amount', p_amount, 'currency', p_currency_code));

  return v_id;
end;
$$;

-- -----------------------------------------------------------------------------
-- void_transaction
--
-- Voiding, never deleting (§32). The row stays visible in history and audit;
-- it simply stops affecting balances.
-- -----------------------------------------------------------------------------

create or replace function public.void_transaction(
  p_user_id uuid,
  p_id      uuid,
  p_reason  text default null
)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_tx public.transactions%rowtype;
begin
  select * into v_tx from public.transactions
  where id = p_id and user_id = p_user_id
  for update;

  if v_tx.id is null then
    raise exception 'TRANSACTION_NOT_FOUND' using errcode = 'P0002';
  end if;
  if v_tx.status = 'voided' then
    -- Idempotent: a double submit must not produce a second audit entry.
    return;
  end if;

  update public.transactions
  set status = 'voided',
      void_reason = nullif(btrim(coalesce(p_reason, '')), '')
  where id = p_id;

  if v_tx.source_account_id is not null then
    perform public.recalculate_account_balance(v_tx.source_account_id);
  end if;
  if v_tx.destination_account_id is not null then
    perform public.recalculate_account_balance(v_tx.destination_account_id);
  end if;

  insert into public.audit_logs
    (actor_user_id, target_user_id, entity_type, entity_id, event_type,
     before_data, after_data, metadata)
  values
    (p_user_id, p_user_id, 'transaction', p_id, 'transaction_voided',
     jsonb_build_object('status', 'confirmed', 'amount', v_tx.amount),
     jsonb_build_object('status', 'voided'),
     jsonb_build_object('reason', coalesce(p_reason, '')));
end;
$$;

-- -----------------------------------------------------------------------------
-- create_account
--
-- The account and its opening_balance transaction are created together.
-- Separately, a crash between them leaves an account whose stated opening
-- balance has no ledger entry behind it.
-- -----------------------------------------------------------------------------

create or replace function public.create_account(
  p_user_id          uuid,
  p_name             text,
  p_type             text,
  p_nature           text,
  p_currency_code    text,
  p_opening_balance  numeric default 0,
  p_institution_name text default null
)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_id uuid;
begin
  insert into public.accounts
    (user_id, name, type, nature, currency_code, opening_balance, institution_name)
  values
    (p_user_id, btrim(p_name), p_type, p_nature, upper(p_currency_code),
     coalesce(p_opening_balance, 0),
     nullif(btrim(coalesce(p_institution_name, '')), ''))
  returning id into v_id;

  -- Only when non-zero: an opening_balance row of 0 is noise in the ledger.
  if coalesce(p_opening_balance, 0) <> 0 then
    insert into public.transactions
      (user_id, type, direction, amount, currency_code, transaction_date,
       destination_account_id, status, description)
    values
      (p_user_id, 'opening_balance',
       case when p_opening_balance < 0 then 'decrease' else 'increase' end,
       abs(p_opening_balance), upper(p_currency_code), current_date,
       v_id, 'confirmed', 'Opening balance');
  end if;

  perform public.recalculate_account_balance(v_id);

  insert into public.audit_logs
    (actor_user_id, target_user_id, entity_type, entity_id, event_type, after_data)
  values
    (p_user_id, p_user_id, 'account', v_id, 'account_created',
     jsonb_build_object('name', p_name, 'type', p_type, 'nature', p_nature));

  return v_id;
end;
$$;

-- -----------------------------------------------------------------------------
-- Integrity check (§36, and Phase 14 §64)
-- -----------------------------------------------------------------------------

create or replace function public.check_balance_integrity(p_user_id uuid)
returns table (account_id uuid, account_name text, cached numeric, derived numeric)
language plpgsql
security definer
set search_path = ''
as $$
begin
  return query
  select a.id, a.name, a.current_balance,
         public.recalculate_account_balance(a.id)
  from public.accounts a
  where a.user_id = p_user_id;
end;
$$;

comment on function public.check_balance_integrity(uuid) is
  'Reports cached vs derived balance per account. Recalculating repairs as it reads, so run it to both detect and fix drift.';

-- Callable by the service role only. These bypass RLS by design.
revoke all on function public.create_transaction from anon, authenticated;
revoke all on function public.void_transaction   from anon, authenticated;
revoke all on function public.create_account     from anon, authenticated;
revoke all on function public.assert_account_access from anon, authenticated;
revoke all on function public.recalculate_account_balance from anon, authenticated;
revoke all on function public.check_balance_integrity from anon, authenticated;


-- ======================================================================
-- 20260913000400_lock_schema_migrations.sql
-- ======================================================================

-- =============================================================================
-- Lock down schema_migrations.
--
-- The migration runner created this table with a plain CREATE TABLE, so
-- Supabase's default grants applied and anon/authenticated received ALL
-- privileges — including TRUNCATE. It holds no user data, but an anonymous
-- visitor being able to erase migration history is exactly the kind of default
-- that should never survive a verification pass.
--
-- Caught by supabase/VERIFY-RLS.sql, which is why that file checks grants and
-- not just policies.
-- =============================================================================

alter table if exists public.schema_migrations enable row level security;
alter table if exists public.schema_migrations force  row level security;

revoke all on public.schema_migrations from anon, authenticated;

-- No policies at all: this table is for the migration runner, which connects
-- as the database owner and is unaffected by RLS grants to PostgREST roles.


-- ======================================================================
-- 20260913000500_reject_income_to_liability.sql
-- ======================================================================

-- =============================================================================
-- Reject income into a liability account.
--
-- Found by the Phase 02 end-to-end test. The shape CHECK only requires income
-- to have a destination; it cannot verify that account's NATURE, because a
-- CHECK constraint may not run a subquery.
--
-- So income into a credit card was accepted, and then had zero balance effect
-- (lib/finance/balance.ts §34: income only applies to assets). The user records
-- income, no balance moves, and nothing reports an error — the worst shape of
-- bug in a ledger, because it is silent.
--
-- Enforced in the RPC, which is the only write path.
-- =============================================================================

create or replace function public.assert_income_destination(
  p_type       text,
  p_account_id uuid
)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_nature text;
begin
  if p_type <> 'income' or p_account_id is null then
    return;
  end if;

  select nature into v_nature from public.accounts where id = p_account_id;

  if v_nature <> 'asset' then
    -- Money arriving on a credit card is a refund (reduces debt) or a
    -- transfer, not income. Both are supported; income is not.
    raise exception 'INCOME_REQUIRES_ASSET' using errcode = 'P0001';
  end if;
end;
$$;

revoke all on function public.assert_income_destination from anon, authenticated;

-- Re-create create_transaction with the extra assertion. Body is otherwise
-- unchanged from 20260913000300.
create or replace function public.create_transaction(
  p_user_id                uuid,
  p_type                   text,
  p_amount                 numeric,
  p_currency_code          text,
  p_transaction_date       date,
  p_source_account_id      uuid default null,
  p_destination_account_id uuid default null,
  p_category_id            uuid default null,
  p_direction              text default null,
  p_merchant_name          text default null,
  p_description            text default null,
  p_notes                  text default null,
  p_refund_of              uuid default null
)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_id uuid;
begin
  if p_amount is null or p_amount <= 0 then
    raise exception 'AMOUNT_NOT_POSITIVE' using errcode = 'P0001';
  end if;

  perform public.assert_account_access(p_user_id, p_source_account_id, p_currency_code);
  perform public.assert_account_access(p_user_id, p_destination_account_id, p_currency_code);
  perform public.assert_income_destination(p_type, p_destination_account_id);

  if p_category_id is not null then
    if not exists (
      select 1 from public.categories
      where id = p_category_id and (is_system or user_id = p_user_id)
    ) then
      raise exception 'CATEGORY_NOT_FOUND' using errcode = 'P0002';
    end if;
  end if;

  perform 1 from public.accounts
  where id in (p_source_account_id, p_destination_account_id)
  order by id
  for update;

  insert into public.transactions (
    user_id, type, direction, amount, currency_code, transaction_date,
    source_account_id, destination_account_id, category_id,
    merchant_name, description, notes, refund_of_transaction_id, status
  ) values (
    p_user_id, p_type, p_direction, p_amount, p_currency_code, p_transaction_date,
    p_source_account_id, p_destination_account_id, p_category_id,
    nullif(btrim(coalesce(p_merchant_name, '')), ''),
    nullif(btrim(coalesce(p_description, '')), ''),
    nullif(btrim(coalesce(p_notes, '')), ''),
    p_refund_of, 'confirmed'
  )
  returning id into v_id;

  if p_source_account_id is not null then
    perform public.recalculate_account_balance(p_source_account_id);
  end if;
  if p_destination_account_id is not null then
    perform public.recalculate_account_balance(p_destination_account_id);
  end if;

  insert into public.audit_logs
    (actor_user_id, target_user_id, entity_type, entity_id, event_type, after_data)
  values
    (p_user_id, p_user_id, 'transaction', v_id, 'transaction_created',
     jsonb_build_object('type', p_type, 'amount', p_amount, 'currency', p_currency_code));

  return v_id;
end;
$$;

revoke all on function public.create_transaction from anon, authenticated;


-- ======================================================================
-- 20260913000600_phase03_obligations.sql
-- ======================================================================

-- =============================================================================
-- Phase 03 — Bills, Receivables and Expected Income
--
-- CORE MODELLING RULE (§4):
--   An obligation is not a transaction. A bill is not an expense; a receivable
--   is not income; expected income is not income. Only actual money movement
--   creates a transaction. Link tables record which transaction settled which
--   obligation, and by how much.
--
-- STATUS (§9, §38):
--   Persisted:  open | partially_paid | paid | cancelled   — lifecycle
--   Derived:    upcoming | due_soon | due_today | overdue   — time
--
--   Time-based states are computed at read time from due_date and the
--   remaining amount. Storing them would mean a daily job whose only purpose
--   is refreshing a label, and a label that is silently wrong between runs.
--
-- Idempotent.
-- =============================================================================

-- -----------------------------------------------------------------------------
-- bills
-- -----------------------------------------------------------------------------

create table if not exists public.bills (
  id            uuid primary key default gen_random_uuid(),
  user_id       uuid not null references auth.users (id) on delete cascade,
  provider_name text not null,
  description   text,
  category_id   uuid references public.categories (id) on delete set null,
  amount        numeric(18, 2) not null,
  currency_code text not null default 'PHP',
  due_date      date not null,
  status        text not null default 'open',
  notes         text,
  is_archived   boolean not null default false,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now()
);

comment on column public.bills.status is
  'Lifecycle only: open | partially_paid | paid | cancelled. Time states (due_soon, overdue) are derived at read time.';

-- -----------------------------------------------------------------------------
-- receivables
-- -----------------------------------------------------------------------------

create table if not exists public.receivables (
  id            uuid primary key default gen_random_uuid(),
  user_id       uuid not null references auth.users (id) on delete cascade,
  party_name    text not null,
  description   text,
  amount        numeric(18, 2) not null,
  currency_code text not null default 'PHP',
  due_date      date,
  status        text not null default 'open',
  notes         text,
  is_archived   boolean not null default false,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now()
);

-- -----------------------------------------------------------------------------
-- expected_income
--
-- Distinct from receivables (§30): a receivable is a defined debt someone owes
-- you; expected income is anticipated money that nobody owes yet — a salary,
-- a stipend, a likely freelance payment.
-- -----------------------------------------------------------------------------

create table if not exists public.expected_income (
  id            uuid primary key default gen_random_uuid(),
  user_id       uuid not null references auth.users (id) on delete cascade,
  source_name   text not null,
  description   text,
  category_id   uuid references public.categories (id) on delete set null,
  amount        numeric(18, 2) not null,
  currency_code text not null default 'PHP',
  expected_date date not null,
  status        text not null default 'open',
  notes         text,
  is_archived   boolean not null default false,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now()
);

do $$
declare t text;
begin
  foreach t in array array['bills', 'receivables', 'expected_income'] loop
    -- One persisted lifecycle vocabulary across all three, so the allocation
    -- function can stay polymorphic.
    if not exists (select 1 from pg_constraint where conname = t || '_status_check') then
      execute format(
        'alter table public.%I add constraint %I check (status in (%L,%L,%L,%L))',
        t, t || '_status_check', 'open', 'partially_paid', 'paid', 'cancelled');
    end if;
    if not exists (select 1 from pg_constraint where conname = t || '_amount_check') then
      execute format('alter table public.%I add constraint %I check (amount > 0)',
                     t, t || '_amount_check');
    end if;
    if not exists (select 1 from pg_constraint where conname = t || '_currency_check') then
      execute format('alter table public.%I add constraint %I check (char_length(currency_code) = 3)',
                     t, t || '_currency_check');
    end if;
    execute format('drop trigger if exists %I on public.%I', t || '_set_updated_at', t);
    execute format(
      'create trigger %I before update on public.%I for each row execute function public.set_updated_at()',
      t || '_set_updated_at', t);
  end loop;
end $$;

create index if not exists bills_user_due_idx on public.bills (user_id, due_date);
create index if not exists bills_open_idx on public.bills (user_id, due_date)
  where status in ('open', 'partially_paid');
create index if not exists receivables_user_due_idx on public.receivables (user_id, due_date);
create index if not exists receivables_open_idx on public.receivables (user_id, due_date)
  where status in ('open', 'partially_paid');
create index if not exists expected_income_user_date_idx
  on public.expected_income (user_id, expected_date);

-- -----------------------------------------------------------------------------
-- Link tables
--
-- amount_applied on both sides (§36) so one transaction can settle several
-- obligations and one obligation can take several transactions. Retrofitting
-- this shape later is painful, so it is here from the start even though the
-- MVP flow is one-to-one.
-- -----------------------------------------------------------------------------

create table if not exists public.bill_payments (
  id             uuid primary key default gen_random_uuid(),
  user_id        uuid not null references auth.users (id) on delete cascade,
  bill_id        uuid not null references public.bills (id) on delete cascade,
  transaction_id uuid not null references public.transactions (id) on delete restrict,
  amount_applied numeric(18, 2) not null check (amount_applied > 0),
  created_at     timestamptz not null default now()
);

create table if not exists public.receivable_payments (
  id             uuid primary key default gen_random_uuid(),
  user_id        uuid not null references auth.users (id) on delete cascade,
  receivable_id  uuid not null references public.receivables (id) on delete cascade,
  transaction_id uuid not null references public.transactions (id) on delete restrict,
  amount_applied numeric(18, 2) not null check (amount_applied > 0),
  created_at     timestamptz not null default now()
);

create table if not exists public.expected_income_receipts (
  id                 uuid primary key default gen_random_uuid(),
  user_id            uuid not null references auth.users (id) on delete cascade,
  expected_income_id uuid not null references public.expected_income (id) on delete cascade,
  transaction_id     uuid not null references public.transactions (id) on delete restrict,
  amount_applied     numeric(18, 2) not null check (amount_applied > 0),
  created_at         timestamptz not null default now()
);

create index if not exists bill_payments_bill_idx on public.bill_payments (bill_id);
create index if not exists bill_payments_tx_idx on public.bill_payments (transaction_id);
create index if not exists receivable_payments_recv_idx on public.receivable_payments (receivable_id);
create index if not exists receivable_payments_tx_idx on public.receivable_payments (transaction_id);
create index if not exists eir_expected_idx on public.expected_income_receipts (expected_income_id);
create index if not exists eir_tx_idx on public.expected_income_receipts (transaction_id);

-- -----------------------------------------------------------------------------
-- Allocation — the concurrency guard (§37, §74)
--
-- The problem this exists to prevent:
--
--   Bill remaining ₱1,000. Two ₱1,000 payments arrive together. Both read
--   "remaining 1,000", both conclude they fit, both insert. The bill ends up
--   ₱2,000 paid against a ₱1,000 obligation.
--
-- Neither invariant can be a CHECK constraint — both are aggregates across
-- rows. Application-level checks lose the race outright: between the read and
-- the write, the other request has already read the same balance.
--
-- The FOR UPDATE row lock is the mechanism. It serialises concurrent callers
-- against the same obligation, so the second reads the first's committed
-- total rather than a stale one.
-- -----------------------------------------------------------------------------

create or replace function public.allocate_payment(
  p_user_id         uuid,
  p_obligation_type text,   -- 'bill' | 'receivable' | 'expected_income'
  p_obligation_id   uuid,
  p_transaction_id  uuid,
  p_amount          numeric
)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_ob_amount    numeric(18,2);
  v_ob_currency  text;
  v_ob_status    text;
  v_ob_owner     uuid;
  v_applied      numeric(18,2);
  v_tx_amount    numeric(18,2);
  v_tx_currency  text;
  v_tx_status    text;
  v_tx_owner     uuid;
  v_tx_applied   numeric(18,2);
  v_link_id      uuid;
  v_new_status   text;
begin
  if p_amount is null or p_amount <= 0 then
    raise exception 'AMOUNT_NOT_POSITIVE' using errcode = 'P0001';
  end if;
  if p_obligation_type not in ('bill', 'receivable', 'expected_income') then
    raise exception 'UNKNOWN_OBLIGATION_TYPE' using errcode = 'P0001';
  end if;

  -- Lock the obligation FIRST and hold it for the rest of the transaction.
  -- Everything below reads committed state because of this line.
  if p_obligation_type = 'bill' then
    select user_id, amount, currency_code, status
      into v_ob_owner, v_ob_amount, v_ob_currency, v_ob_status
    from public.bills where id = p_obligation_id for update;
  elsif p_obligation_type = 'receivable' then
    select user_id, amount, currency_code, status
      into v_ob_owner, v_ob_amount, v_ob_currency, v_ob_status
    from public.receivables where id = p_obligation_id for update;
  else
    select user_id, amount, currency_code, status
      into v_ob_owner, v_ob_amount, v_ob_currency, v_ob_status
    from public.expected_income where id = p_obligation_id for update;
  end if;

  if v_ob_owner is null or v_ob_owner <> p_user_id then
    -- Same error either way: a distinguishable "forbidden" confirms existence.
    raise exception 'OBLIGATION_NOT_FOUND' using errcode = 'P0002';
  end if;
  if v_ob_status = 'cancelled' then
    raise exception 'OBLIGATION_CANCELLED' using errcode = 'P0001';
  end if;

  select user_id, amount, currency_code, status
    into v_tx_owner, v_tx_amount, v_tx_currency, v_tx_status
  from public.transactions where id = p_transaction_id for update;

  if v_tx_owner is null or v_tx_owner <> p_user_id then
    raise exception 'TRANSACTION_NOT_FOUND' using errcode = 'P0002';
  end if;
  if v_tx_status <> 'confirmed' then
    raise exception 'TRANSACTION_NOT_CONFIRMED' using errcode = 'P0001';
  end if;
  if v_tx_currency <> v_ob_currency then
    -- Cross-currency settlement is permanently out of scope (master plan §11).
    raise exception 'CURRENCY_MISMATCH' using errcode = 'P0001';
  end if;

  -- Totals recomputed INSIDE the lock. This is the whole point.
  if p_obligation_type = 'bill' then
    select coalesce(sum(amount_applied), 0) into v_applied
    from public.bill_payments where bill_id = p_obligation_id;
  elsif p_obligation_type = 'receivable' then
    select coalesce(sum(amount_applied), 0) into v_applied
    from public.receivable_payments where receivable_id = p_obligation_id;
  else
    select coalesce(sum(amount_applied), 0) into v_applied
    from public.expected_income_receipts where expected_income_id = p_obligation_id;
  end if;

  if v_applied + p_amount > v_ob_amount then
    raise exception 'EXCEEDS_OBLIGATION_REMAINING' using errcode = 'P0001';
  end if;

  -- A transaction may settle several obligations, but never more than itself.
  select coalesce((
    select sum(amount_applied) from public.bill_payments where transaction_id = p_transaction_id
  ), 0) + coalesce((
    select sum(amount_applied) from public.receivable_payments where transaction_id = p_transaction_id
  ), 0) + coalesce((
    select sum(amount_applied) from public.expected_income_receipts where transaction_id = p_transaction_id
  ), 0)
  into v_tx_applied;

  if v_tx_applied + p_amount > v_tx_amount then
    raise exception 'EXCEEDS_TRANSACTION_AMOUNT' using errcode = 'P0001';
  end if;

  if p_obligation_type = 'bill' then
    insert into public.bill_payments (user_id, bill_id, transaction_id, amount_applied)
    values (p_user_id, p_obligation_id, p_transaction_id, p_amount) returning id into v_link_id;
  elsif p_obligation_type = 'receivable' then
    insert into public.receivable_payments (user_id, receivable_id, transaction_id, amount_applied)
    values (p_user_id, p_obligation_id, p_transaction_id, p_amount) returning id into v_link_id;
  else
    insert into public.expected_income_receipts
      (user_id, expected_income_id, transaction_id, amount_applied)
    values (p_user_id, p_obligation_id, p_transaction_id, p_amount) returning id into v_link_id;
  end if;

  v_applied := v_applied + p_amount;
  v_new_status := case
    when v_applied >= v_ob_amount then 'paid'
    when v_applied > 0            then 'partially_paid'
    else 'open'
  end;

  if p_obligation_type = 'bill' then
    update public.bills set status = v_new_status where id = p_obligation_id;
  elsif p_obligation_type = 'receivable' then
    update public.receivables set status = v_new_status where id = p_obligation_id;
  else
    update public.expected_income set status = v_new_status where id = p_obligation_id;
  end if;

  insert into public.audit_logs
    (actor_user_id, target_user_id, entity_type, entity_id, event_type, after_data)
  values
    (p_user_id, p_user_id, p_obligation_type, p_obligation_id, 'payment_linked',
     jsonb_build_object('transaction_id', p_transaction_id,
                        'amount_applied', p_amount,
                        'status', v_new_status));

  return v_link_id;
end;
$$;

-- -----------------------------------------------------------------------------
-- unlink_payment (§55)
--
-- Removing a link never deletes the transaction — the money did move.
-- -----------------------------------------------------------------------------

create or replace function public.unlink_payment(
  p_user_id         uuid,
  p_obligation_type text,
  p_link_id         uuid
)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_ob_id     uuid;
  v_owner     uuid;
  v_ob_amount numeric(18,2);
  v_applied   numeric(18,2);
  v_status    text;
begin
  if p_obligation_type = 'bill' then
    select bill_id, user_id into v_ob_id, v_owner
    from public.bill_payments where id = p_link_id;
  elsif p_obligation_type = 'receivable' then
    select receivable_id, user_id into v_ob_id, v_owner
    from public.receivable_payments where id = p_link_id;
  else
    select expected_income_id, user_id into v_ob_id, v_owner
    from public.expected_income_receipts where id = p_link_id;
  end if;

  if v_owner is null or v_owner <> p_user_id then
    raise exception 'LINK_NOT_FOUND' using errcode = 'P0002';
  end if;

  if p_obligation_type = 'bill' then
    perform 1 from public.bills where id = v_ob_id for update;
    delete from public.bill_payments where id = p_link_id;
    select amount into v_ob_amount from public.bills where id = v_ob_id;
    select coalesce(sum(amount_applied), 0) into v_applied
      from public.bill_payments where bill_id = v_ob_id;
  elsif p_obligation_type = 'receivable' then
    perform 1 from public.receivables where id = v_ob_id for update;
    delete from public.receivable_payments where id = p_link_id;
    select amount into v_ob_amount from public.receivables where id = v_ob_id;
    select coalesce(sum(amount_applied), 0) into v_applied
      from public.receivable_payments where receivable_id = v_ob_id;
  else
    perform 1 from public.expected_income where id = v_ob_id for update;
    delete from public.expected_income_receipts where id = p_link_id;
    select amount into v_ob_amount from public.expected_income where id = v_ob_id;
    select coalesce(sum(amount_applied), 0) into v_applied
      from public.expected_income_receipts where expected_income_id = v_ob_id;
  end if;

  v_status := case
    when v_applied >= v_ob_amount then 'paid'
    when v_applied > 0            then 'partially_paid'
    else 'open'
  end;

  if p_obligation_type = 'bill' then
    update public.bills set status = v_status where id = v_ob_id;
  elsif p_obligation_type = 'receivable' then
    update public.receivables set status = v_status where id = v_ob_id;
  else
    update public.expected_income set status = v_status where id = v_ob_id;
  end if;

  insert into public.audit_logs
    (actor_user_id, target_user_id, entity_type, entity_id, event_type, after_data)
  values
    (p_user_id, p_user_id, p_obligation_type, v_ob_id, 'payment_unlinked',
     jsonb_build_object('status', v_status));
end;
$$;

revoke all on function public.allocate_payment from anon, authenticated;
revoke all on function public.unlink_payment   from anon, authenticated;

-- -----------------------------------------------------------------------------
-- RLS
-- -----------------------------------------------------------------------------

do $$
declare t text;
begin
  foreach t in array array['bills','receivables','expected_income',
                           'bill_payments','receivable_payments','expected_income_receipts'] loop
    execute format('alter table public.%I enable row level security', t);
    execute format('alter table public.%I force  row level security', t);
    execute format('drop policy if exists %I on public.%I', t || '_select_own', t);
    execute format(
      'create policy %I on public.%I for select to authenticated using (user_id = (select auth.uid()))',
      t || '_select_own', t);
    execute format('revoke all on public.%I from anon, authenticated', t);
    execute format('grant select on public.%I to authenticated', t);
  end loop;
end $$;


-- ======================================================================
-- 20260913000700_void_updates_obligations.sql
-- ======================================================================

-- =============================================================================
-- Voiding a transaction must release its allocations (§57).
--
-- Without this, voiding a ₱1,899 payment leaves the bill still marked paid:
-- the money no longer moved, but the obligation still believes it was settled.
-- The user sees a bill they have not paid, marked paid, with no transaction
-- behind it.
--
-- So void now: releases every link, recomputes each affected obligation's
-- status, then voids — all in one transaction.
-- =============================================================================

create or replace function public.void_transaction(
  p_user_id uuid,
  p_id      uuid,
  p_reason  text default null
)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_tx  public.transactions%rowtype;
  v_rec record;
begin
  select * into v_tx from public.transactions
  where id = p_id and user_id = p_user_id
  for update;

  if v_tx.id is null then
    raise exception 'TRANSACTION_NOT_FOUND' using errcode = 'P0002';
  end if;
  if v_tx.status = 'voided' then
    return;  -- idempotent
  end if;

  -- Release allocations and restate each obligation.
  for v_rec in
    select 'bill' as kind, bill_id as ob_id from public.bill_payments
      where transaction_id = p_id
    union all
    select 'receivable', receivable_id from public.receivable_payments
      where transaction_id = p_id
    union all
    select 'expected_income', expected_income_id from public.expected_income_receipts
      where transaction_id = p_id
  loop
    if v_rec.kind = 'bill' then
      perform 1 from public.bills where id = v_rec.ob_id for update;
      delete from public.bill_payments
        where transaction_id = p_id and bill_id = v_rec.ob_id;
      update public.bills b set status = case
          when coalesce((select sum(amount_applied) from public.bill_payments
                         where bill_id = b.id), 0) >= b.amount then 'paid'
          when coalesce((select sum(amount_applied) from public.bill_payments
                         where bill_id = b.id), 0) > 0 then 'partially_paid'
          else 'open' end
        where b.id = v_rec.ob_id and b.status <> 'cancelled';

    elsif v_rec.kind = 'receivable' then
      perform 1 from public.receivables where id = v_rec.ob_id for update;
      delete from public.receivable_payments
        where transaction_id = p_id and receivable_id = v_rec.ob_id;
      update public.receivables r set status = case
          when coalesce((select sum(amount_applied) from public.receivable_payments
                         where receivable_id = r.id), 0) >= r.amount then 'paid'
          when coalesce((select sum(amount_applied) from public.receivable_payments
                         where receivable_id = r.id), 0) > 0 then 'partially_paid'
          else 'open' end
        where r.id = v_rec.ob_id and r.status <> 'cancelled';

    else
      perform 1 from public.expected_income where id = v_rec.ob_id for update;
      delete from public.expected_income_receipts
        where transaction_id = p_id and expected_income_id = v_rec.ob_id;
      update public.expected_income e set status = case
          when coalesce((select sum(amount_applied) from public.expected_income_receipts
                         where expected_income_id = e.id), 0) >= e.amount then 'paid'
          when coalesce((select sum(amount_applied) from public.expected_income_receipts
                         where expected_income_id = e.id), 0) > 0 then 'partially_paid'
          else 'open' end
        where e.id = v_rec.ob_id and e.status <> 'cancelled';
    end if;

    insert into public.audit_logs
      (actor_user_id, target_user_id, entity_type, entity_id, event_type, after_data)
    values
      (p_user_id, p_user_id, v_rec.kind, v_rec.ob_id, 'payment_unlinked',
       jsonb_build_object('reason', 'transaction_voided', 'transaction_id', p_id));
  end loop;

  update public.transactions
  set status = 'voided',
      void_reason = nullif(btrim(coalesce(p_reason, '')), '')
  where id = p_id;

  if v_tx.source_account_id is not null then
    perform public.recalculate_account_balance(v_tx.source_account_id);
  end if;
  if v_tx.destination_account_id is not null then
    perform public.recalculate_account_balance(v_tx.destination_account_id);
  end if;

  insert into public.audit_logs
    (actor_user_id, target_user_id, entity_type, entity_id, event_type,
     before_data, after_data, metadata)
  values
    (p_user_id, p_user_id, 'transaction', p_id, 'transaction_voided',
     jsonb_build_object('status', 'confirmed', 'amount', v_tx.amount),
     jsonb_build_object('status', 'voided'),
     jsonb_build_object('reason', coalesce(p_reason, '')));
end;
$$;

revoke all on function public.void_transaction from anon, authenticated;


-- ======================================================================
-- 20260913000800_phase04_documents.sql
-- ======================================================================

-- =============================================================================
-- Phase 04 — Documents and Image Processing
--
-- Files live in a PRIVATE Supabase Storage bucket. Metadata lives here.
-- HelloDeploy's filesystem is never the system of record (§5) — containers are
-- replaced on every deploy.
--
-- ACCESS MODEL
--   The bucket has no policies for anon or authenticated at all. Every read
--   goes through a short-lived signed URL minted server-side after an
--   ownership check; every write goes through the upload action using the
--   service role. Storage RLS would otherwise have to re-derive ownership from
--   the object path, and a path-parsing mistake there is a cross-user file
--   leak.
--
-- RETENTION (§26)
--   The OCR-quality source survives until the extraction is resolved, not
--   until OCR merely completes — Phase 05 retries need it, and a display WebP
--   at 1800px/q85 is compressed for viewing, not for reading small print.
--
-- Idempotent.
-- =============================================================================

create table if not exists public.documents (
  id                   uuid primary key default gen_random_uuid(),
  user_id              uuid not null references auth.users (id) on delete cascade,
  document_type        text not null default 'other',

  -- Original, as received. Filename is metadata only — never a storage key.
  original_filename    text,
  original_mime_type   text,
  original_size_bytes  bigint,
  content_hash         text,

  storage_bucket       text not null default 'hello-pera-documents',
  original_path        text,
  display_path         text,
  thumbnail_path       text,

  display_mime_type    text,
  display_size_bytes   bigint,
  thumbnail_size_bytes bigint,
  width                integer,
  height               integer,
  page_count           integer,

  processing_status    text not null default 'uploaded',
  processing_error     text,
  retention_status     text not null default 'original_retained',

  is_archived          boolean not null default false,
  created_at           timestamptz not null default now(),
  updated_at           timestamptz not null default now()
);

comment on column public.documents.original_filename is
  'Display metadata only. Storage keys are generated UUIDs — a user-supplied filename in a path is a traversal waiting to happen.';
comment on column public.documents.retention_status is
  'original_retained until the Phase 05 extraction is confirmed or discarded. OCR retry needs the full-quality source.';

do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'documents_type_check') then
    alter table public.documents add constraint documents_type_check check (
      document_type in ('receipt','screenshot','bill','payment_confirmation','bank_record',
                        'ewallet_record','invoice','statement','salary_record','other'));
  end if;
  if not exists (select 1 from pg_constraint where conname = 'documents_processing_check') then
    alter table public.documents add constraint documents_processing_check check (
      processing_status in ('uploaded','processing','ready','failed'));
  end if;
  if not exists (select 1 from pg_constraint where conname = 'documents_retention_check') then
    alter table public.documents add constraint documents_retention_check check (
      retention_status in ('original_retained','original_temporary','original_deleted','optimized_only'));
  end if;
end $$;

create index if not exists documents_user_created_idx
  on public.documents (user_id, created_at desc);
create index if not exists documents_user_type_idx
  on public.documents (user_id, document_type);
-- Duplicate detection in Phase 05 looks up by hash within a user.
create index if not exists documents_user_hash_idx
  on public.documents (user_id, content_hash) where content_hash is not null;
create index if not exists documents_failed_idx
  on public.documents (user_id) where processing_status = 'failed';

drop trigger if exists documents_set_updated_at on public.documents;
create trigger documents_set_updated_at before update on public.documents
  for each row execute function public.set_updated_at();

-- -----------------------------------------------------------------------------
-- document_links (§41)
--
-- Created now rather than in Phase 05: the many-to-many shape is what allows
-- one receipt to evidence several records, and one record to have several
-- documents. Retrofitting it after documents exist means a migration plus a
-- backfill.
-- -----------------------------------------------------------------------------

create table if not exists public.document_links (
  id          uuid primary key default gen_random_uuid(),
  user_id     uuid not null references auth.users (id) on delete cascade,
  document_id uuid not null references public.documents (id) on delete cascade,
  entity_type text not null,
  entity_id   uuid not null,
  created_at  timestamptz not null default now()
);

do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'document_links_entity_check') then
    alter table public.document_links add constraint document_links_entity_check check (
      entity_type in ('transaction','bill','receivable','expected_income'));
  end if;
end $$;

create unique index if not exists document_links_unique_idx
  on public.document_links (document_id, entity_type, entity_id);
create index if not exists document_links_entity_idx
  on public.document_links (entity_type, entity_id);

-- -----------------------------------------------------------------------------
-- Storage bucket
-- -----------------------------------------------------------------------------

insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values (
  'hello-pera-documents',
  'hello-pera-documents',
  false,                              -- never public: these are bank records
  8388608,                            -- 8 MB. HelloDeploy's nginx caps requests
                                      -- at 10 MB; 8 leaves room for multipart
                                      -- overhead. See PLATFORM-HELLODEPLOY.md Q1.
  array['image/jpeg','image/png','image/webp','image/heic','image/heif','application/pdf']
)
on conflict (id) do update
  set public = false,
      file_size_limit = excluded.file_size_limit,
      allowed_mime_types = excluded.allowed_mime_types;

-- No policies on storage.objects for anon or authenticated.
-- Reads use server-minted signed URLs; writes use the service role.
drop policy if exists "hellopera documents are private" on storage.objects;

-- -----------------------------------------------------------------------------
-- RLS
-- -----------------------------------------------------------------------------

alter table public.documents      enable row level security;
alter table public.documents      force  row level security;
alter table public.document_links enable row level security;
alter table public.document_links force  row level security;

drop policy if exists documents_select_own on public.documents;
create policy documents_select_own on public.documents
  for select to authenticated using (user_id = (select auth.uid()));

drop policy if exists document_links_select_own on public.document_links;
create policy document_links_select_own on public.document_links
  for select to authenticated using (user_id = (select auth.uid()));

revoke all on public.documents, public.document_links from anon, authenticated;
grant select on public.documents, public.document_links to authenticated;


-- ======================================================================
-- 20260913000900_phase05_ocr_extraction.sql
-- ======================================================================

-- =============================================================================
-- Phase 05 — OCR and Financial Extraction
--
-- CORE PRINCIPLE (§4): OCR is not authoritative.
--
--   Document -> OCR -> Extraction -> User Review -> Confirmation -> Record
--
-- Nothing derived from a document may change a balance before a human confirms
-- it. That is enforced structurally: extraction rows hold JSON, never money,
-- and the only path to a transaction is confirm_extraction() below, which
-- requires the extraction to be in pending_review.
--
-- Idempotent.
-- =============================================================================

create table if not exists public.ocr_jobs (
  id                 uuid primary key default gen_random_uuid(),
  user_id            uuid not null references auth.users (id) on delete cascade,
  document_id        uuid not null references public.documents (id) on delete cascade,
  provider           text not null,
  status             text not null default 'queued',
  attempt_count      integer not null default 0,
  started_at         timestamptz,
  completed_at       timestamptz,
  failed_at          timestamptz,
  error_code         text,
  error_message_safe text,
  duration_ms        integer,
  created_at         timestamptz not null default now(),
  updated_at         timestamptz not null default now()
);

-- One active job per document (§45). Prevents a double-click from paying a
-- provider twice for the same page.
create unique index if not exists ocr_jobs_one_active_idx
  on public.ocr_jobs (document_id)
  where status in ('queued', 'processing');

create index if not exists ocr_jobs_user_idx on public.ocr_jobs (user_id, created_at desc);
create index if not exists ocr_jobs_failed_idx
  on public.ocr_jobs (user_id) where status = 'failed';

create table if not exists public.ocr_results (
  id                 uuid primary key default gen_random_uuid(),
  user_id            uuid not null references auth.users (id) on delete cascade,
  document_id        uuid not null references public.documents (id) on delete cascade,
  ocr_job_id         uuid references public.ocr_jobs (id) on delete set null,
  provider           text not null,
  raw_text           text,
  overall_confidence numeric(4, 3),
  provider_metadata  jsonb not null default '{}'::jsonb,
  created_at         timestamptz not null default now()
);

comment on column public.ocr_results.raw_text is
  'Document text. Never written to application logs (§58) — it contains account numbers and balances.';

create index if not exists ocr_results_document_idx on public.ocr_results (document_id);

create table if not exists public.extraction_results (
  id                uuid primary key default gen_random_uuid(),
  user_id           uuid not null references auth.users (id) on delete cascade,
  document_id       uuid not null references public.documents (id) on delete cascade,
  ocr_result_id     uuid references public.ocr_results (id) on delete set null,
  document_type     text,
  target_type       text,
  status            text not null default 'pending_review',
  -- Structured fields stay as JSON until a human confirms. Deliberately not
  -- numeric columns: an extraction is a proposal, and giving it the shape of a
  -- financial record invites something to read it as one.
  structured_data   jsonb not null default '{}'::jsonb,
  field_confidence  jsonb not null default '{}'::jsonb,
  validation_errors jsonb not null default '[]'::jsonb,
  corrected_data    jsonb,
  confirmed_at      timestamptz,
  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now()
);

do $$
begin
  if not exists (select 1 from pg_constraint where conname='ocr_jobs_status_check') then
    alter table public.ocr_jobs add constraint ocr_jobs_status_check
      check (status in ('queued','processing','completed','failed','cancelled'));
  end if;
  if not exists (select 1 from pg_constraint where conname='extraction_status_check') then
    alter table public.extraction_results add constraint extraction_status_check
      check (status in ('pending_review','confirmed','discarded','failed'));
  end if;
  if not exists (select 1 from pg_constraint where conname='extraction_target_check') then
    alter table public.extraction_results add constraint extraction_target_check
      check (target_type is null or target_type in
        ('transaction','bill','receivable','expected_income','unknown'));
  end if;
end $$;

create index if not exists extraction_document_idx on public.extraction_results (document_id);
create index if not exists extraction_pending_idx
  on public.extraction_results (user_id, created_at desc) where status = 'pending_review';

drop trigger if exists ocr_jobs_set_updated_at on public.ocr_jobs;
create trigger ocr_jobs_set_updated_at before update on public.ocr_jobs
  for each row execute function public.set_updated_at();
drop trigger if exists extraction_set_updated_at on public.extraction_results;
create trigger extraction_set_updated_at before update on public.extraction_results
  for each row execute function public.set_updated_at();

-- -----------------------------------------------------------------------------
-- Confirmation (§33, §83)
--
-- The ONLY path from an extraction to a financial record.
--
-- Idempotent by status transition: the row must be pending_review, and the
-- update to 'confirmed' happens in the same transaction as the record creation.
-- A double-click therefore cannot create two transactions — the second call
-- finds the row already confirmed and stops.
-- -----------------------------------------------------------------------------

create or replace function public.confirm_extraction(
  p_user_id       uuid,
  p_extraction_id uuid,
  p_entity_type   text,
  p_entity_id     uuid
)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_owner       uuid;
  v_status      text;
  v_document_id uuid;
begin
  -- Lock first: two simultaneous confirms must not both see pending_review.
  select user_id, status, document_id
    into v_owner, v_status, v_document_id
  from public.extraction_results
  where id = p_extraction_id
  for update;

  if v_owner is null or v_owner <> p_user_id then
    raise exception 'EXTRACTION_NOT_FOUND' using errcode = 'P0002';
  end if;
  if v_status = 'confirmed' then
    raise exception 'ALREADY_CONFIRMED' using errcode = 'P0001';
  end if;
  if v_status <> 'pending_review' then
    raise exception 'NOT_PENDING_REVIEW' using errcode = 'P0001';
  end if;

  update public.extraction_results
  set status = 'confirmed', target_type = p_entity_type, confirmed_at = now()
  where id = p_extraction_id;

  -- Link the document to whatever the confirmation created, so the receipt is
  -- reachable from the record and vice versa.
  insert into public.document_links (user_id, document_id, entity_type, entity_id)
  values (p_user_id, v_document_id, p_entity_type, p_entity_id)
  on conflict do nothing;

  insert into public.audit_logs
    (actor_user_id, target_user_id, entity_type, entity_id, event_type, after_data)
  values
    (p_user_id, p_user_id, 'extraction', p_extraction_id, 'extraction_confirmed',
     jsonb_build_object('entity_type', p_entity_type, 'entity_id', p_entity_id));
end;
$$;

create or replace function public.discard_extraction(
  p_user_id uuid,
  p_extraction_id uuid
)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare v_owner uuid; v_status text;
begin
  select user_id, status into v_owner, v_status
  from public.extraction_results where id = p_extraction_id for update;

  if v_owner is null or v_owner <> p_user_id then
    raise exception 'EXTRACTION_NOT_FOUND' using errcode = 'P0002';
  end if;
  if v_status = 'confirmed' then
    -- Discarding after confirmation would orphan a real financial record.
    raise exception 'ALREADY_CONFIRMED' using errcode = 'P0001';
  end if;

  update public.extraction_results set status = 'discarded' where id = p_extraction_id;

  insert into public.audit_logs
    (actor_user_id, target_user_id, entity_type, entity_id, event_type)
  values (p_user_id, p_user_id, 'extraction', p_extraction_id, 'extraction_discarded');
end;
$$;

revoke all on function public.confirm_extraction from anon, authenticated;
revoke all on function public.discard_extraction from anon, authenticated;

-- -----------------------------------------------------------------------------
-- RLS
-- -----------------------------------------------------------------------------

do $$
declare t text;
begin
  foreach t in array array['ocr_jobs','ocr_results','extraction_results'] loop
    execute format('alter table public.%I enable row level security', t);
    execute format('alter table public.%I force  row level security', t);
    execute format('drop policy if exists %I on public.%I', t||'_select_own', t);
    execute format(
      'create policy %I on public.%I for select to authenticated using (user_id = (select auth.uid()))',
      t||'_select_own', t);
    execute format('revoke all on public.%I from anon, authenticated', t);
    execute format('grant select on public.%I to authenticated', t);
  end loop;
end $$;


-- ======================================================================
-- 20260913001000_phase07_recurring_forecasting.sql
-- ======================================================================

-- =============================================================================
-- Phase 07 — Recurring Transactions and Forecasting
--
-- CORE MODELLING RULE (§4, §12):
--   A recurring rule is not money. It is a statement about what is expected to
--   happen. Generating an occurrence creates an *expectation*, never a
--   transaction — only actual money movement does that, exactly as Phase 03
--   separates an obligation from the payment that settles it.
--
-- GENERATION ARCHITECTURE (§16, the "recommended hybrid"):
--   rule_type = bill             -> generates a real row in bills
--   rule_type = expected_income  -> generates a real row in expected_income
--   rule_type = income | expense -> generates expected_events
--
--   Bills and expected income already have lifecycle, allocation and display
--   status built in Phase 03; re-implementing those on expected_events would
--   be two sets of rules for one concept. Plain recurring income and expense
--   have no such home, so they get the generic row.
--
-- IDEMPOTENCY (§18, §60, §64):
--   Generation is defined by a uniqueness constraint, not by careful code.
--   Every generated row carries (recurring_rule_id, occurrence_date) with a
--   unique index, so a double-fired scheduler, an overlapping retry and a
--   lazy top-up on page load all collide harmlessly on insert.
--
-- Idempotent.
-- =============================================================================

-- -----------------------------------------------------------------------------
-- recurring_rules (§7)
-- -----------------------------------------------------------------------------

create table if not exists public.recurring_rules (
  id                   uuid primary key default gen_random_uuid(),
  user_id              uuid not null references auth.users (id) on delete cascade,
  rule_type            text not null,
  name                 text not null,
  description          text,
  amount               numeric(18, 2) not null,
  currency_code        text not null default 'PHP',
  frequency            text not null,
  interval_count       integer not null default 1,
  -- §10, §11 — which day the rule lands on. Null means "same day as start".
  day_of_month         integer,
  day_of_week          integer,
  start_date           date not null,
  end_date             date,
  -- The next date not yet generated. Advanced by the generator, never by a
  -- read, so a crashed run resumes rather than skipping.
  next_occurrence_date date,
  account_id           uuid references public.accounts (id) on delete set null,
  category_id          uuid references public.categories (id) on delete set null,
  -- Carried onto generated bills / expected income so the row reads naturally.
  provider_name        text,
  source_name          text,
  is_active            boolean not null default true,
  is_paused            boolean not null default false,
  created_at           timestamptz not null default now(),
  updated_at           timestamptz not null default now()
);

do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'recurring_rules_type_check') then
    alter table public.recurring_rules add constraint recurring_rules_type_check
      check (rule_type in ('income', 'expense', 'bill', 'expected_income'));
  end if;

  -- §8 — a small, closed set. RRULE-style recurrence is explicitly out (§8).
  if not exists (select 1 from pg_constraint where conname = 'recurring_rules_frequency_check') then
    alter table public.recurring_rules add constraint recurring_rules_frequency_check
      check (frequency in ('weekly', 'biweekly', 'monthly', 'quarterly', 'yearly'));
  end if;

  -- §9 — "every N". Zero would generate the same date forever.
  if not exists (select 1 from pg_constraint where conname = 'recurring_rules_interval_check') then
    alter table public.recurring_rules add constraint recurring_rules_interval_check
      check (interval_count >= 1 and interval_count <= 52);
  end if;

  if not exists (select 1 from pg_constraint where conname = 'recurring_rules_amount_check') then
    alter table public.recurring_rules add constraint recurring_rules_amount_check
      check (amount > 0);
  end if;

  -- §10 — 29..31 are accepted and clamped to the month's last day at
  -- generation time; see lib/recurring/schedule.ts.
  if not exists (select 1 from pg_constraint where conname = 'recurring_rules_dom_check') then
    alter table public.recurring_rules add constraint recurring_rules_dom_check
      check (day_of_month is null or (day_of_month between 1 and 31));
  end if;

  -- §11 — ISO: 1 = Monday .. 7 = Sunday.
  if not exists (select 1 from pg_constraint where conname = 'recurring_rules_dow_check') then
    alter table public.recurring_rules add constraint recurring_rules_dow_check
      check (day_of_week is null or (day_of_week between 1 and 7));
  end if;

  -- §13 — an end before the start would generate nothing, silently.
  if not exists (select 1 from pg_constraint where conname = 'recurring_rules_dates_check') then
    alter table public.recurring_rules add constraint recurring_rules_dates_check
      check (end_date is null or end_date >= start_date);
  end if;
end $$;

create index if not exists recurring_rules_user_idx
  on public.recurring_rules (user_id, start_date);
-- The generator's own query: live rules with something still to generate.
create index if not exists recurring_rules_due_idx
  on public.recurring_rules (next_occurrence_date)
  where is_active and not is_paused;

drop trigger if exists recurring_rules_set_updated_at on public.recurring_rules;
create trigger recurring_rules_set_updated_at before update on public.recurring_rules
  for each row execute function public.set_updated_at();

-- -----------------------------------------------------------------------------
-- expected_events (§15)
--
-- Generic expectations for recurring income and expense. Bills and expected
-- income get native Phase 03 rows instead (§16).
-- -----------------------------------------------------------------------------

create table if not exists public.expected_events (
  id                    uuid primary key default gen_random_uuid(),
  user_id               uuid not null references auth.users (id) on delete cascade,
  recurring_rule_id     uuid references public.recurring_rules (id) on delete cascade,
  event_type            text not null,
  name                  text not null,
  amount                numeric(18, 2) not null,
  currency_code         text not null default 'PHP',
  scheduled_date        date not null,
  status                text not null default 'scheduled',
  account_id            uuid references public.accounts (id) on delete set null,
  category_id           uuid references public.categories (id) on delete set null,
  -- §39, §40 — the transaction that fulfilled this expectation, if any.
  actual_transaction_id uuid references public.transactions (id) on delete set null,
  -- §43 — a user may exclude a single occurrence from the projection without
  -- skipping it, e.g. "this bonus is not certain enough to plan against".
  include_in_forecast   boolean not null default true,
  created_at            timestamptz not null default now(),
  updated_at            timestamptz not null default now()
);

do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'expected_events_type_check') then
    alter table public.expected_events add constraint expected_events_type_check
      check (event_type in ('income', 'expense', 'bill', 'expected_income'));
  end if;

  -- §15. `overdue` is NOT here: like Phase 03's display statuses it is derived
  -- from scheduled_date at read time, so it cannot be silently stale between
  -- scheduler runs.
  if not exists (select 1 from pg_constraint where conname = 'expected_events_status_check') then
    alter table public.expected_events add constraint expected_events_status_check
      check (status in ('scheduled', 'fulfilled', 'skipped', 'cancelled'));
  end if;

  if not exists (select 1 from pg_constraint where conname = 'expected_events_amount_check') then
    alter table public.expected_events add constraint expected_events_amount_check
      check (amount > 0);
  end if;

  -- A fulfilled event must say what fulfilled it, and an unfulfilled one must
  -- not pretend to (§39).
  if not exists (select 1 from pg_constraint where conname = 'expected_events_fulfilled_check') then
    alter table public.expected_events add constraint expected_events_fulfilled_check
      check (
        (status = 'fulfilled' and actual_transaction_id is not null)
        or (status <> 'fulfilled' and actual_transaction_id is null)
      );
  end if;
end $$;

-- §18 — the whole of idempotent generation, in one line. A rule cannot
-- produce the same date twice no matter how many schedulers fire.
create unique index if not exists expected_events_rule_date_uidx
  on public.expected_events (recurring_rule_id, scheduled_date)
  where recurring_rule_id is not null;

create index if not exists expected_events_user_date_idx
  on public.expected_events (user_id, scheduled_date);
create index if not exists expected_events_forecast_idx
  on public.expected_events (user_id, scheduled_date)
  where status = 'scheduled' and include_in_forecast;

drop trigger if exists expected_events_set_updated_at on public.expected_events;
create trigger expected_events_set_updated_at before update on public.expected_events
  for each row execute function public.set_updated_at();

-- -----------------------------------------------------------------------------
-- Generated Phase 03 rows (§16, §18)
--
-- A recurring bill produces a real bill, so it inherits Phase 03's lifecycle,
-- allocation and derived status for free. The provenance columns are what make
-- that generation idempotent.
-- -----------------------------------------------------------------------------

alter table public.bills
  add column if not exists recurring_rule_id uuid references public.recurring_rules (id) on delete set null,
  add column if not exists occurrence_date date;

alter table public.expected_income
  add column if not exists recurring_rule_id uuid references public.recurring_rules (id) on delete set null,
  add column if not exists occurrence_date date;

create unique index if not exists bills_rule_occurrence_uidx
  on public.bills (recurring_rule_id, occurrence_date)
  where recurring_rule_id is not null;

create unique index if not exists expected_income_rule_occurrence_uidx
  on public.expected_income (recurring_rule_id, occurrence_date)
  where recurring_rule_id is not null;

-- -----------------------------------------------------------------------------
-- job_runs (§20a)
--
-- Introduced here because this is the first scheduler. Phases 08, 11, 13 and
-- 14 reuse it; PHASE-13 §48-51 builds the admin view over it rather than
-- inventing it late, by which point three phases would have run unprotected.
--
-- No user_id: these are system runs, not user data. Phase 13's admin view is
-- the only reader, so the table is not exposed to the client at all.
-- -----------------------------------------------------------------------------

create table if not exists public.job_runs (
  id           uuid primary key default gen_random_uuid(),
  job_type     text not null,
  status       text not null default 'running',
  started_at   timestamptz not null default now(),
  completed_at timestamptz,
  duration_ms  integer,
  error_code   text,
  metadata     jsonb not null default '{}'::jsonb
);

do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'job_runs_status_check') then
    alter table public.job_runs add constraint job_runs_status_check
      check (status in ('running', 'succeeded', 'failed', 'partial'));
  end if;
end $$;

create index if not exists job_runs_type_started_idx
  on public.job_runs (job_type, started_at desc);
-- Finding a wedged run: one that claims to be running and never finished.
create index if not exists job_runs_running_idx
  on public.job_runs (job_type) where status = 'running';

-- -----------------------------------------------------------------------------
-- RLS
--
-- Client reads its own rows; every write goes through a server action
-- (master plan §33). `job_runs` is not user data and is not exposed at all.
-- -----------------------------------------------------------------------------

do $$
declare t text;
begin
  foreach t in array array['recurring_rules', 'expected_events'] loop
    execute format('alter table public.%I enable row level security', t);
    execute format('alter table public.%I force  row level security', t);
    execute format('drop policy if exists %I on public.%I', t || '_select_own', t);
    execute format(
      'create policy %I on public.%I for select to authenticated using (user_id = (select auth.uid()))',
      t || '_select_own', t);
    execute format('revoke all on public.%I from anon, authenticated', t);
    execute format('grant select on public.%I to authenticated', t);
  end loop;
end $$;

alter table public.job_runs enable row level security;
alter table public.job_runs force  row level security;
revoke all on public.job_runs from anon, authenticated;


-- ======================================================================
-- 20260913001100_phase07_generation_rpc.sql
-- ======================================================================

-- =============================================================================
-- Phase 07 — occurrence generation and job bookkeeping
--
-- Two concerns, deliberately separate:
--
--   generate_occurrence()  inserts ONE occurrence for ONE rule, idempotently.
--   run_job_*()            the §20a advisory-lock and job_runs bookkeeping.
--
-- The date arithmetic is NOT here. It lives in lib/recurring/schedule.ts,
-- where it is unit-tested across month-end, leap years and DST — the cases
-- that actually break recurrence. SQL computes nothing it cannot be tested
-- on; it enforces uniqueness, which is the part that must be atomic.
--
-- Idempotent.
-- =============================================================================

-- -----------------------------------------------------------------------------
-- generate_occurrence (§16, §18, §60)
--
-- Routes by rule type to the right home, and relies on the unique indexes for
-- idempotency rather than a read-then-write check, which loses the race
-- outright: between "does it exist?" and "insert", a concurrent run has
-- already inserted.
--
-- Returns the id created, or null when the occurrence already existed.
-- -----------------------------------------------------------------------------

create or replace function public.generate_occurrence(
  p_rule_id         uuid,
  p_occurrence_date date
)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  r public.recurring_rules%rowtype;
  v_id uuid;
begin
  select * into r from public.recurring_rules where id = p_rule_id;
  if not found then
    raise exception 'RULE_NOT_FOUND' using errcode = 'P0001';
  end if;

  -- §21, §24 — a paused or ended rule generates nothing. Checked here as well
  -- as in the caller so a stale worklist cannot resurrect a stopped rule.
  if not r.is_active or r.is_paused then
    return null;
  end if;
  if p_occurrence_date < r.start_date then
    return null;
  end if;
  if r.end_date is not null and p_occurrence_date > r.end_date then
    return null;
  end if;

  if r.rule_type = 'bill' then
    insert into public.bills (
      user_id, provider_name, description, category_id, amount, currency_code,
      due_date, status, recurring_rule_id, occurrence_date
    ) values (
      r.user_id, coalesce(r.provider_name, r.name), r.description, r.category_id,
      r.amount, r.currency_code, p_occurrence_date, 'open', r.id, p_occurrence_date
    )
    on conflict do nothing
    returning id into v_id;

  elsif r.rule_type = 'expected_income' then
    insert into public.expected_income (
      user_id, source_name, description, category_id, amount, currency_code,
      expected_date, status, recurring_rule_id, occurrence_date
    ) values (
      r.user_id, coalesce(r.source_name, r.name), r.description, r.category_id,
      r.amount, r.currency_code, p_occurrence_date, 'open', r.id, p_occurrence_date
    )
    on conflict do nothing
    returning id into v_id;

  else
    insert into public.expected_events (
      user_id, recurring_rule_id, event_type, name, amount, currency_code,
      scheduled_date, status, account_id, category_id
    ) values (
      r.user_id, r.id, r.rule_type, r.name, r.amount, r.currency_code,
      p_occurrence_date, 'scheduled', r.account_id, r.category_id
    )
    on conflict do nothing
    returning id into v_id;
  end if;

  return v_id;
end $$;

revoke all on function public.generate_occurrence from anon, authenticated;

-- -----------------------------------------------------------------------------
-- advance_rule_cursor
--
-- Moves next_occurrence_date forward. Separate from generation so a failure
-- part-way through a rule's backlog leaves the cursor where work resumes,
-- rather than skipping the dates it had not reached.
-- -----------------------------------------------------------------------------

create or replace function public.advance_rule_cursor(
  p_rule_id uuid,
  p_next    date
)
returns void
language sql
security definer
set search_path = ''
as $$
  update public.recurring_rules
     set next_occurrence_date = p_next
   where id = p_rule_id;
$$;

revoke all on function public.advance_rule_cursor from anon, authenticated;

-- -----------------------------------------------------------------------------
-- Job bookkeeping (§20a)
--
-- begin_job takes the advisory lock and opens a job_runs row, or returns null
-- when another run holds the lock. An advisory lock is released automatically
-- if the session dies, so a crashed run cannot wedge the schedule the way a
-- lock table would.
--
-- This is defence in depth. The unique indexes in the previous migration are
-- what make generation *correct*; the lock stops two runs wasting effort and
-- racing on the same rows.
-- -----------------------------------------------------------------------------

create or replace function public.begin_job(p_job_type text)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_id uuid;
begin
  if not pg_try_advisory_lock(hashtext(p_job_type)) then
    return null;   -- another run owns this job type; exit without error
  end if;

  insert into public.job_runs (job_type, status)
  values (p_job_type, 'running')
  returning id into v_id;

  return v_id;
end $$;

create or replace function public.finish_job(
  p_job_id     uuid,
  p_job_type   text,
  p_status     text,
  p_error_code text default null,
  p_metadata   jsonb default '{}'::jsonb
)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  update public.job_runs
     set status       = p_status,
         completed_at = now(),
         duration_ms  = (extract(epoch from (now() - started_at)) * 1000)::integer,
         error_code   = p_error_code,
         metadata     = coalesce(p_metadata, '{}'::jsonb)
   where id = p_job_id;

  -- Released explicitly on the happy path; the session ending releases it
  -- anyway, which is what makes a crash safe.
  perform pg_advisory_unlock(hashtext(p_job_type));
end $$;

revoke all on function public.begin_job  from anon, authenticated;
revoke all on function public.finish_job from anon, authenticated;


-- ======================================================================
-- 20260914000100_phase07_generation_orchestrator.sql
-- ======================================================================

-- =============================================================================
-- Phase 07 — generation orchestrator, schema corrections, and scheduling
--
-- Completes the Phase 07 database layer. Three concerns:
--
--   1. Columns §15 and §66 specify that the first migration did not create.
--   2. run_recurring_generation() — the function the scheduler calls. The
--      parts existed (generate_occurrence, advance_rule_cursor, begin_job,
--      finish_job); nothing orchestrated them, so nothing generated anything.
--   3. The pg_cron schedule itself (§2, §20).
--
-- ## On putting date arithmetic in SQL
--
-- The previous migration's header says the date math lives in TypeScript and
-- not here. That was right when SQL only had to insert one occurrence it was
-- handed. It cannot hold once Postgres owns the schedule (§2: HelloDeploy has
-- no scheduler, so generation runs in the database), because the job must
-- decide *which* dates to generate with no application in the loop.
--
-- So the walk is transcribed here, and `lib/recurring/sql-parity.test.ts`
-- asserts it still agrees with `lib/recurring/schedule.ts` across every
-- frequency, interval and month-end case. That is the same device
-- `lib/finance/sql-parity.test.ts` already uses for the balance matrix, and
-- for the same reason: two hand-written copies of one rule is how a system
-- drifts into showing a number its own repair job disagrees with.
--
-- The anchor rule is preserved exactly: occurrence N is computed from the
-- rule's START DATE, never from occurrence N-1. A rule on the 31st clamps to
-- 28 February and returns to 31 March. Walking from the previous occurrence
-- would move it permanently to the 28th.
--
-- Idempotent.
-- =============================================================================

-- -----------------------------------------------------------------------------
-- 1. Missing columns
-- -----------------------------------------------------------------------------

-- §66 — a user who edits a generated event must not have that edit erased by
-- the next regeneration. DATA-MODEL.md already documented this column; the
-- table never had it.
alter table public.expected_events
  add column if not exists detached_from_rule boolean not null default false;

-- §15 — provenance for events materialised into another table.
alter table public.expected_events
  add column if not exists source_entity_type text;
alter table public.expected_events
  add column if not exists source_entity_id   uuid;

do $$
begin
  if not exists (
    select 1 from pg_constraint where conname = 'expected_events_source_entity_type_check'
  ) then
    alter table public.expected_events
      add constraint expected_events_source_entity_type_check
      check (source_entity_type is null
             or source_entity_type in ('bill', 'expected_income', 'transaction'));
  end if;
end $$;

-- -----------------------------------------------------------------------------
-- 2. Recurrence arithmetic (§8–§11)
--
-- occurrence_at(rule, step) — the transcription of occurrenceAt() in
-- lib/recurring/schedule.ts. Immutable and side-effect free, so it is safe to
-- call in a loop and cheap enough not to matter.
-- -----------------------------------------------------------------------------

create or replace function public.occurrence_at(
  p_frequency      text,
  p_interval_count integer,
  p_start_date     date,
  p_day_of_month   integer,
  p_day_of_week    integer,
  p_step           integer
)
returns date
language plpgsql
immutable
set search_path = ''
as $$
declare
  v_day_step   integer;
  v_month_step integer;
  v_base       date;
  v_shift      integer;
  v_anchor_day integer;
  v_months     integer;
  v_first      date;      -- first of the target month
  v_day        integer;
begin
  -- Weekly family: a plain day offset from a (possibly shifted) base.
  v_day_step := case p_frequency
                  when 'weekly'   then 7
                  when 'biweekly' then 14
                  else null
                end;

  if v_day_step is not null then
    v_base := p_start_date;
    -- §11 — shift forward to the named weekday; every later occurrence keeps
    -- the same offset. isodow: 1 = Monday .. 7 = Sunday, matching the TS.
    if p_day_of_week is not null then
      v_shift := (p_day_of_week - extract(isodow from p_start_date)::integer + 7) % 7;
      v_base  := v_base + v_shift;
    end if;
    return v_base + (p_step * v_day_step * p_interval_count);
  end if;

  -- Monthly family.
  v_month_step := case p_frequency
                    when 'monthly'   then 1
                    when 'quarterly' then 3
                    when 'yearly'    then 12
                    else 1
                  end;

  v_anchor_day := coalesce(p_day_of_month, extract(day from p_start_date)::integer);
  v_months     := p_step * v_month_step * p_interval_count;

  v_first := (date_trunc('month', p_start_date::timestamp)
              + make_interval(months => v_months))::date;

  -- §10 — clamp to the last valid day of the target month. Computed
  -- explicitly rather than leaning on interval arithmetic's own clamping, so
  -- the rule is visible and the parity test can check it.
  v_day := least(
    v_anchor_day,
    extract(day from (v_first + interval '1 month' - interval '1 day'))::integer
  );

  return v_first + (v_day - 1);
end $$;

revoke all on function public.occurrence_at from anon, authenticated;

-- -----------------------------------------------------------------------------
-- 3. run_recurring_generation (§17, §19, §20, §20a, §59, §64, §65)
--
-- One function so the advisory lock is taken, held and released inside a
-- SINGLE call. begin_job/finish_job take a SESSION-level lock across two
-- separate round trips, which is correct for pg_cron (one session) but leaks
-- the lock under a pooler, where the unlock can land on a different backend
-- than the lock. §2's fallbacks are all HTTP-shaped, so that had to be closed
-- before one of them is ever used.
--
-- Idempotency does not depend on the lock. The unique indexes from the first
-- migration are what make a second run a no-op (§65: "the constraint is the
-- guarantee; the lock is the optimisation").
--
-- p_horizon_days defaults to 90 (§17) — never generate years ahead.
-- -----------------------------------------------------------------------------

create or replace function public.run_recurring_generation(
  p_horizon_days integer default 90,
  p_user_id      uuid    default null   -- null = every user; set for the lazy check
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_job_type    text := 'recurring_generation';
  -- The lock key is per-user for a scoped run and global for the scheduled
  -- one. Without this, one user opening /forecast would take the same lock the
  -- hourly job uses, and every other user's on-load generation in that moment
  -- would skip — a lock contending on work that never overlaps, since the two
  -- runs touch different rows.
  v_lock_key    text;
  v_job_id      uuid;
  v_rule        record;
  v_today       date;
  v_horizon_end date;
  v_step        integer;
  v_date        date;
  v_created     integer := 0;
  v_examined    integer := 0;
  v_rules       integer := 0;
  v_next        date;
  v_id          uuid;
  v_status      text := 'succeeded';
  v_error       text := null;
  v_max_steps   constant integer := 4000;  -- mirrors MAX_STEPS in schedule.ts
begin
  -- §20a — skip silently when another run owns this job type. Not an error:
  -- the schedule firing over a slow run is expected, not exceptional.
  v_lock_key := case
                  when p_user_id is null then v_job_type
                  else v_job_type || ':' || p_user_id::text
                end;

  if not pg_try_advisory_lock(hashtext(v_lock_key)) then
    return jsonb_build_object('skipped', true, 'reason', 'locked');
  end if;

  insert into public.job_runs (job_type, status)
  values (v_job_type, 'running')
  returning id into v_job_id;

  begin
    for v_rule in
      select r.*, coalesce(p.timezone, 'Asia/Manila') as tz
        from public.recurring_rules r
        -- LEFT, not INNER: a rule whose profile row is somehow missing must
        -- still generate (falling back to Asia/Manila) rather than silently
        -- stop producing occurrences with nothing to show why.
        left join public.profiles p on p.id = r.user_id
       where r.is_active
         and not r.is_paused
         and (p_user_id is null or r.user_id = p_user_id)
    loop
      -- §47, §2 — "today" is the user's local date. cron.schedule fires in
      -- UTC; deriving the date from that would generate a day early or late
      -- for every user west or east of it.
      v_today       := (now() at time zone v_rule.tz)::date;
      v_horizon_end := v_today + p_horizon_days;

      -- §13, §24 — an ended rule generates nothing further.
      if v_rule.end_date is not null and v_rule.end_date < v_today then
        continue;
      end if;

      v_rules := v_rules + 1;
      v_next  := null;

      for v_step in 0 .. v_max_steps loop
        v_date := public.occurrence_at(
          v_rule.frequency, v_rule.interval_count, v_rule.start_date,
          v_rule.day_of_month, v_rule.day_of_week, v_step
        );

        exit when v_date > v_horizon_end;
        exit when v_rule.end_date is not null and v_date > v_rule.end_date;

        -- §59 — never before start_date. Occurrences at or before today are
        -- still generated when they fall on/after the cursor, so a rule
        -- created mid-month does not silently lose its current occurrence.
        if v_date >= v_rule.start_date
           and v_date >= coalesce(v_rule.next_occurrence_date, v_rule.start_date)
        then
          v_examined := v_examined + 1;
          v_id := public.generate_occurrence(v_rule.id, v_date);
          -- null means the unique index rejected a duplicate: the idempotent
          -- path, and the reason a second run changes nothing (§64).
          if v_id is not null then
            v_created := v_created + 1;
          end if;
        end if;

        if v_date > v_today then
          v_next := least(coalesce(v_next, v_date), v_date);
        end if;
      end loop;

      -- Advance the cursor to the first occurrence still in the future. Left
      -- where it is when the horizon holds nothing further, so work resumes
      -- there rather than skipping dates never reached.
      if v_next is not null then
        perform public.advance_rule_cursor(v_rule.id, v_next);
      end if;
    end loop;

  exception when others then
    v_status := 'failed';
    v_error  := sqlstate;
  end;

  update public.job_runs
     set status       = v_status,
         completed_at = now(),
         duration_ms  = (extract(epoch from (now() - started_at)) * 1000)::integer,
         error_code   = v_error,
         metadata     = jsonb_build_object(
                          'rules', v_rules,
                          'examined', v_examined,
                          'created', v_created,
                          'horizon_days', p_horizon_days,
                          'scoped_user', p_user_id
                        )
   where id = v_job_id;

  perform pg_advisory_unlock(hashtext(v_lock_key));

  return jsonb_build_object(
    'job_id', v_job_id, 'status', v_status, 'rules', v_rules,
    'created', v_created, 'examined', v_examined, 'error_code', v_error
  );
end $$;

revoke all on function public.run_recurring_generation from anon, authenticated;

-- -----------------------------------------------------------------------------
-- 4. Schedule (§2, §20)
--
-- Hourly rather than daily: rules belong to users in many timezones and the
-- job resolves "today" per user, so an hourly pass picks up each local
-- midnight within the hour. The body is a function call, not inline logic, so
-- the schedule stays stable while the logic changes and the same function can
-- be replayed manually by an admin (PHASE-13 §50).
--
-- Guarded: pg_cron is not available on every Supabase plan, and a migration
-- that hard-fails there would block every later migration. If this is skipped,
-- the lazy safety check in the application (§19) still generates on access —
-- correctness does not depend on cron, only timeliness.
-- -----------------------------------------------------------------------------

do $$
begin
  create extension if not exists pg_cron;

  -- Re-scheduling the same job name would stack duplicate schedules.
  if exists (select 1 from cron.job where jobname = 'recurring_generation') then
    perform cron.unschedule('recurring_generation');
  end if;

  perform cron.schedule(
    'recurring_generation',
    '0 * * * *',
    $cron$ select public.run_recurring_generation() $cron$
  );

  raise notice 'pg_cron: recurring_generation scheduled hourly';
exception when others then
  -- insufficient_privilege, undefined_file, undefined_table — all mean the
  -- same thing operationally: no pg_cron here.
  raise warning 'pg_cron unavailable (%): recurring generation will rely on the application-side safety check (PHASE-07 §19). See PHASE-07 §2 for fallbacks.', sqlerrm;
end $$;
